```python
import math

def calculate_area(shape, dimensions):
    """
    Calculates the area of a given shape with the given dimensions.

    :param shape: str, the shape (e.g., 'circle', 'rectangle', 'square')
    :param dimensions: tuple, the dimensions of the shape (e.g., (radius, width, height))
    :return: float, the area of the shape
    """

    # Define functions for calculating area based on the shape
    if shape == 'circle':
        def calculate_circle_area(radius):
            return math.pi * (radius ** 2)

        return calculate_circle_area(dimensions[0])

    elif shape == 'rectangle':
        def calculate_rectangle_area(width, height):
            return width * height

        return calculate_rectangle_area(*dimensions)

    elif shape == 'square':
        def calculate_square_area(side):
            return side ** 2

        return calculate_square_area(*dimensions)

    # If the shape is not recognized, raise an exception
    else:
        raise ValueError(f"Invalid shape '{shape}'. Supported shapes are 'circle', 'rectangle', and 'square'.")
```

